SELECT TABLE_NAME FROM USER_TABLES;

SELECT COLUMN_NAME
FROM ALL_TAB_COLUMNS
WHERE TABLE_NAME = 'LHSMEMBER3';

SELECT TABLE_NAME
FROM (
    SELECT TABLE_NAME, ROWNUM AS RNUM
    FROM USER_TABLES
)
WHERE RNUM = 1;

-- 설명을 위한 추정 형태
SELECT ... FROM MEMBER
WHERE ID = '입력ID' AND PW = '입력PW';

SELECT ... FROM BOARD
WHERE 작성일 BETWEEN TO_DATE('시작일', 'YYYY-MM-DD')
                AND TO_DATE('종료일', 'YYYY-MM-DD');

-- 패키지 인터페이스 선언
CREATE OR REPLACE PACKAGE MY_PKG AS
    FUNCTION ADD_ONE(N NUMBER) RETURN NUMBER;
END;
/

-- 함수 구현
CREATE OR REPLACE PACKAGE BODY MY_PKG AS
    FUNCTION ADD_ONE(N NUMBER)
    RETURN NUMBER IS
    BEGIN
        RETURN N + 1;
    END;
END;
/

SELECT NAME
FROM TEST
WHERE ROWNUM = 3;

SELECT NAME
FROM (
    SELECT NAME, ROWNUM AS RNUM
    FROM TEST
)
WHERE RNUM = 3;
